  // the fan is listed; every entry is thrown twice, once mirrored.
  static const std::array<Vector, 5> coin_velocities = {{
    { 2.5f, -4.5f }, { 2.f, -5.f },
    { 1.5f, -5.5f }, { 1.f, -6.f }, { 0.5f, -6.5f }
  }};

  for (const auto& vector : coin_velocities)
  {
    for (const float side : { 1.f, -1.f })
    {
      const Vector velocity = Vector(vector.x, vector.y * side) * (mag - gameRandom.randf(rand));
      Sector::get().add<HeavyCoin>(position, velocity, m_count_stats, m_sprite);
    }
  }

  remove_me();
}

