import re,sys
s=open(sys.argv[1]).read()
ts=open('data/images/tiles.strf').read()
water=set(); solid=set()
# parse "tiles" groups with ids and attributes
for m in re.finditer(r'\(tiles\b(.*?)\n\s*\)', ts, re.S):
    b=m.group(1)
    ids=re.search(r'\(ids([\d\s]+)\)',b)
    if not ids: continue
    ids=list(map(int,ids.group(1).split()))
    for key,st in (('water',water),('solids',solid)):
        a=re.search(r'\(%s([\d\s]+)\)'%key,b)
        if a:
            for i,v in zip(ids,map(int,a.group(1).split())):
                if v: st.add(i)
for m in re.finditer(r'\(tile\s+\(id (\d+)\)(.*?)\n\s*\)',ts,re.S):
    if '(water #t)' in m.group(2): water.add(int(m.group(1)))
    if '(solid #t)' in m.group(2): solid.add(int(m.group(1)))
for m in re.finditer(r'\(tilemap(.*?)\(tiles([-\d\s]+)\)',s,re.S):
    hdr=m.group(1)
    w=int(re.search(r'\(width (\d+)',hdr).group(1)); h=int(re.search(r'\(height (\d+)',hdr).group(1))
    sol=re.search(r'\(solid (#t|#f)',hdr).group(1)
    raw=list(map(int,m.group(2).split())); t=[];i=0
    while i<len(raw):
        if raw[i]<0: t+= [raw[i+1]]*(-raw[i]); i+=2
        else: t.append(raw[i]); i+=1
    if len(t)!=w*h: print('len mismatch',len(t),w*h); continue
    c=int(sys.argv[2])
    col=''.join('W' if t[r*w+c] in water else ('#' if sol=='#t' and t[r*w+c] in solid else ('.' if t[r*w+c]==0 else 'o')) for r in range(h))
